# Allow-list exporter for the Nicopedia byte-level HTP generation milestone.
#
# Publishes only aggregate fields from the device generation runs: byte
# counts, UTF-8 stats, parity/AR gate magnitudes, timing, and thermal
# records.  Generated bytes, prompt text, article/token data, checkpoints,
# serials, ADB endpoints, absolute paths, and every content fingerprint
# (generated_sha256, prompt_sha256, checkpoint_parameter_hash) NEVER enter
# the output bundle.
param(
    [switch]$SelfTest,
    [string]$ReportRoot = "build/reports/nicopedia-htp-generation",
    [string]$OutputRoot = "docs/results/qnn-nicopedia-htp-generation-2026-08",
    [string]$SourceCommit = ""
