    [ordered]@{ limitation = "Sampling is deterministic per platform only (splitmix64 + fp64 softmax); cross-platform last-ulp exp differences are not claimed bit-identical."; scope = "sampling" },
    [ordered]@{ limitation = "Stop is MaxNewBytes only; there is no EOS token. Display is lossless: invalid/truncated bytes are \xNN-escaped, never dropped."; scope = "protocol" },
