    bundle = "qnn-nicopedia-htp-generation-2026-08"
    generated = (Get-Date -Format "yyyy-MM-dd")
    source_commit = $SourceCommit
    summary = "Nicopedia byte-level generation on the QNN HTP graph from HTP-trained checkpoints (L6 seeds 1/2/4, L19 seed 1): fixed-prefix CPU/HTP parity, 8-step AR parity, then greedy/sampled generation. Aggregate results only."
    files = [ordered]@{}
}
