$readme = @"
# Nicopedia byte-level HTP generation, August 2026

This milestone loads the HTP-trained Nicopedia checkpoint into a QNN HTP
graph and runs byte-level generation. The generation forward's numerical
operations execute on HTP; CPU performs prompt encoding, the 32-byte rolling
context window, sampling, and host control. QNN automatic differentiation is
not used, and no NPU-only inference claim is made.

## Protocol

- Byte vocabulary (V=256, no EOS); context is always a rolling 32-byte
  window.  Shorter prompts are NUL-padded at the front; longer prompts use
  the last 32 bytes (training-window semantics).
- Generation stops only at MaxNewBytes (1..1024).
- Every run is gated: 4 fixed-prefix CPU/HTP parity rows (logits max abs
  error < 2e-2, probabilities < 5e-3) and an 8-step autoregressive parity run
  (same tolerance; divergence is blocked when the CPU top-1/top-2 margin at
  the decision point exceeds 0.01).
- Display is lossless: invalid or truncated bytes are \xNN-escaped, never
  dropped.

## Results

- Aggregate only: byte counts, UTF-8 validity stats, parity/AR error
  magnitudes, gate booleans, timing, and thermal records.
- Prompt text, generated bytes, article sets, token rows, checkpoints,
  serials, and all content fingerprints are private and excluded from this
  bundle by the allow-list exporter.

Attribution: This research used the "Nicopedia data" provided by Dwango Co.,
Ltd. through the IDR Dataset Provision Service of the National Institute of
Informatics (NII). Use is limited to non-commercial research. Derived
checkpoint artifacts are not redistributed.
"@
[IO.File]::WriteAllText((Join-Path $output "README.md"), $readme + "`n", [Text.UTF8Encoding]::new($false))

if ($SelfTest) {
    $bundleFiles = @(Get-ChildItem -LiteralPath $output -File)
    foreach ($file in $bundleFiles) {
        if ($file.Name -notin $allowList) { throw "Self-test: non-allow-listed file in output: $($file.Name)" }
    }
    $manifestText = Get-Content -Raw -LiteralPath (Join-Path $output "manifest.json")
    if ($manifestText -notmatch '"qnn-nicopedia-htp-generation-2026-08"') { throw "Self-test: manifest bundle mismatch" }
    # Leak scan: the fixture's generated bytes, prompt fingerprint, and
    # checkpoint identity must never appear anywhere in the bundle.
    $leakPattern = '(?i)generated_hex|generated_sha256|prompt_sha256|host_generated_sha256|checkpoint_parameter_hash|checkpoint_sha256|fnv1a64|\.ckpt|NPRTCKPTV1|/data/local/tmp/|/data/user/|C:\\Users|prompt\.bin'
    foreach ($file in $bundleFiles) {
        $content = Get-Content -Raw -LiteralPath $file.FullName
        if ($content -match $leakPattern) {
            throw "Self-test: private content leaked into $($file.Name)"
        }
        if ($file.Name -eq 'manifest.json') { continue }
        # Manifest sha256 values are 64 hex chars by design; every other file
        # must not contain long hex runs (generated bytes) or \x escapes.
        if ($content -match '\\x[0-9a-f]{2}' -or $content -match '[0-9a-f]{32,}') {
            throw "Self-test: escaped/hex content leaked into $($file.Name)"
        }
    }
    # The allow list must reject the private keys when present in reports.
    $map = Read-KeyValueReport $fixtureReport
    $public = Select-PublicFields $map
    if ($public.Contains('generated_hex') -or $public.Contains('checkpoint_parameter_hash') -or
        $public.Contains('prompt_byte_count') -or $public.Contains('host_generated_sha256')) {
        throw "Self-test: private field leaked through Select-PublicFields"
    }
    Write-Host "qnn_nicopedia_htp_generation_exporter_self_test=PASS files=$($bundleFiles.Count)"
}
Write-Host "qnn_nicopedia_htp_generation_exporter=PASS output=$output"